package gen:node;

world node {
    use aap:caps/types@0.1.0.{heartbeat-report};

    import wasi:clocks/wall-clock@0.2.0;
    import aap:caps/http-client@0.1.0;
    import aap:caps/notifier@0.1.0;

    export run: func(feed-url: string) -> heartbeat-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

/// How many times to offer the notification before giving up. The contract
/// requires `notified == true` on every output, so if the channel never
/// accepts, the node traps instead of returning a report that breaks it.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Note: recording `last-input` in a shared store is not possible
        // here. This node holds no state capability (`aap:caps/state-rw`),
        // and its `with` clause is its entire authority.

        // Clock: read the time once.
        let seconds = wall_clock::now().seconds;

        // HTTP: one fetch. A transport failure is carried as zero characters.
        // A host outside the allowlist traps at the boundary.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: report the heartbeat to the 'digest' channel.
        let message = format!(
            "heartbeat at {seconds}: fetched {fetched} characters from {feed_url}"
        );
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            // Producing no output is better than producing one that violates
            // `ensures notified == true`.
            panic!("notification channel refused the heartbeat");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

